    def movesToMakeZigzag(self, nums):
        n = len(nums)
        res0 = 0
        for i in range(0, n, 2):
            nei = min(nums[j] for j in [i - 1, i + 1] if 0 <= j <= n-1)
            if nums[i] >= nei:
                res0 += nums[i] - nei + 1
        res1 = 0
        for i in range(1, n, 2):
            nei = min(nums[j] for j in [i - 1, i + 1] if 0 <= j <= n-1)
            if nums[i] >= nei:
                res1 += nums[i] - nei + 1
        return min(res0, res1)

def shortest_to_char(s, c):
    if not s or not c:
        return []

    indexes = [i for i, ch in enumerate(s) if ch == c]
    if not indexes:
        return []

    return [ min(abs(i - ic) for ic in indexes) for i in range(len(s)) ]

import numpy as np
from itertools import accumulate
def sieve_primes(n):
    sieve = np.ones(n // 2, dtype = np.bool)
    limit = 1 + int(n ** 0.5)

    for a in range(3, limit, 2):
        if sieve[a // 2]:
            sieve[a * a // 2::a] = False

    prime_indexes = 2 * np.nonzero(sieve)[0].astype(int) + 1
    prime_indexes[0] = 2
    return set(map(str, prime_indexes))

primes = sieve_primes(10 ** 6)

def all_primes(s):
    if int(s) < 10:
        return s in primes
    for n in accumulate(s[:-1]):
        if n in primes:
            m = s[len(n):]
            if m in primes or all_primes(m):
                return True

