    def read_data():
        n, k, p, x, y = map(int, input().split())
        As = list(map(int, input().split()))
        return n, k, p, x, y, As

    def solve(n, k, p, x, y, As):
        '''median (As + Bs) >= y
        sum(As + Bs) <= x
        1 <= Bi <= p
        '''
        middle = n // 2
        As.sort(reverse=True)
        sumA = sum(As)
        minSum = sumA + 1 * (n - k)
        if minSum > x:
            return ['-1']
        num_a_over_y = len([1 for a in As if a >= y])
