            return ['1'] * (n - k)
        min_num_y = middle + 1 - num_a_over_y
        if min_num_y > n - k:
            return ['-1']
        minSum2 = sumA + min_num_y * y + (n - k - min_num_y) * 1
        if minSum2 > x:
            return ['-1']
        return [str(y)] * min_num_y + ['1'] * (n - k - min_num_y)

    def __starting_point():
