        m=sum(i!=j for i,j in zip(h,h[1:]+h[:1]))
        comb=Factorial(m).comb
        print((pow(k,m,M)-sum(comb(m,i)*comb(m-i,i)*pow(k-2,m-i-i,M)for i in range(m//2+1)))*pow(k,n-m,M)*pow(2,M-2,M)%M)
    main()

