        total_use = sum(use_count)
        for i in range(n+1):
            p = getpar(par,i)
            if(p == i):
                if(total_use - use[p] < sz[p]):
                    return False
        return True
    while lo < hi:
        mid = (lo+hi+1)//2
        if solve(mid):
            lo = mid
        else:
            hi = mid-1
