def chain_arith_deriv(n, k):
    if len(prime_factors(n)) < 2:
        return "{} is a prime number".format(n)
    chain = [n]
    while k > 1:
        k, n = k-1, arith_deriv(n)
        chain.append(n)
    return chain


def arith_deriv(n):
    factors = prime_factors(n)
    return sum(n * factors.count(factor) // factor for factor in set(factors)) or 1


def prime_factors(n):
    if n < 2:
        return []
    factors = []
    for k in (2, 3):
        while n % k == 0:
            n //= k
            factors.append(k)
    k = 5
    step = 2
    while k * k <= n:
        if n % k:
            k += step
            step = 6 - step
        else:
            n //= k
            factors.append(k)
    if n > 1:
        factors.append(n)
    return factors

class Solution:
    def maxSubarraySumCircular(self, A: List[int]) -> int:
        N = len(A)
        if(N==0):
            return 0
        curr_max = A[0]
        global_max = A[0]
        curr_min = A[0]
        global_min = A[0]
        flag = 0 
        if(A[0]>=0):
            flag=1

        for i in range(1, N):
            if(A[i]>=0):
                flag=1
            if(curr_max >= 0):
                curr_max = curr_max + A[i]    
            else:
                curr_max = A[i]

            if(curr_min >= 0):
                curr_min = A[i]
            else:
                curr_min = curr_min + A[i] 

            if(curr_max > global_max):
                global_max = curr_max
            if(curr_min < global_min):
                global_min = curr_min
        if(flag==0):
            return max(A)
        return max(global_max, sum(A) - global_min)

