        memo, count = [True]*7, [0]*7
        for L in gen(i, j):
            for x,(k,l) in enumerate(L):
                memo[x] = memo[x] and 0 <= k < sz and 0 <= l < sz and grid[k][l] == p
                count[x] += memo[x]
            if not any(memo):
                return max(count[0], count[1]+count[2], count[3]+count[4], count[5]+count[6])+1 >= con
        return True

    if sz >= con <= len(moves):
