def operator_insertor(n):
    result = []

    for ops in product(["+", "-", ""], repeat=8):
        expression = "".join(a+b for a, b in zip("123456789", list(ops) + [""]))
        res = eval(expression)
        if res == n:
            result.append(len(expression) - 9)

    return min(result, default=None)

import math
def nth_perm(n,d):
    digits = [str(i) for i in range(d)]
    out = ''
    for i in range(1, d):
        cycles = math.ceil(n/math.factorial(d-i))
        out += digits.pop((cycles % (d-i+1)) - 1)
    return out + digits.pop()

