    def mobius(x):
        assert x >= 1
        divcnt = 0
        for p in range(2, x + 1):
            if p*p > x:
                break
            if x % p != 0:
                continue
            x //= p
            if x % p == 0:
                return 0
            else:
                divcnt ^= 1
        if x > 1:
            divcnt ^= 1
        return (-1)**divcnt
