from collections import deque
def ruSna():
    input = sys.stdin.readline
    def slidemax(X, k):
        q = deque([])
        ret = []
        for i in range(len(X)):
            while q and q[-1][1] <= X[i]:
                q.pop()
            deque.append(q, (i+k, X[i]))
            if q[0][0] == i:
                deque.popleft(q)
            if i >= k-1:
                ret.append(q[0][1])
        return ret

