            m = max(B + [0])
            s += m
            for i in range(l-1):
                A[i] += C[i] - m
                A[-i-1] += C[-i-1] - m
        else:
            C = slidemax([0]*(W-l)+B+[0]*(W-l), W - l + 1)
            A = [a+c for a, c in zip(A, C)]
