            x = a
            while x > 0:
                ret += bit[x]
                x -= x & (-1 * x)
            return ret

        def add(self,l,r,w):
            l = l + (1-self.mode)
            r = r + (1-self.mode)
            self.bitadd(l,-1*w*l,self.bit1)
            self.bitadd(r,w*r,self.bit1)
