def toggle(m):
    ups, end = m.group(1), m.group(2)
    off = '*' * bool(end)
    return f'*{ups.lower()}{off}{end}'                # Toggle Shift ON if uppercase presents, and then OFF if lowercase after

def tv_remote(words):
