                nn[v1] -= 1
                adj[u1].remove(v1)
                adj[v1].remove(u1)
            while q:
                v = q.popleft()
                nk -= 1
                for u in adj[v]:
                    nn[u] -= 1
                    if nn[u] == k - 1:
                        q.append(u)
            res[i - 1] = nk
        return res
