class Solution:
    def isBoomerang(self, points: List[List[int]]) -> bool:
        x1, y1 = points[0]
        x2, y2 = points[1]
        x3, y3 = points[2]

        return (y2 - y1) * (x3 - x1) != (y3 - y1) * (x2 - x1)

class Solution:
    def scoreOfParentheses(self, S: str) -> int:
        ans, val = 0, 1
        for i in range(len(S) - 1):
            if S[i: i+2] == '((': val *= 2
            if S[i: i+2] == '()': ans += val
            if S[i: i+2] == '))': val //= 2
        return ans

