        if m not in memo:
            if m < 0:
                memo[m] = 0
            if m == 0:
                memo[m] = 1
            half = m//2
            memo[m] = (solve(half) + solve(half - 1) + solve(half - 2) + solve(half - 3)) % MOD
        return memo[m]

    t = int(input())
