    #https://atcoder.jp/contests/abc168/submissions/13414936
    mod = 10**9 + 7
    N,*AB = map(int,open(0).read().split())
    def std(a,b):
        """
        a,bを既約にする
        """
        if a == 0:
            return(0,int(b!=0))
        g = gcd(a,b)
        a,b = a// g, b//g
        return(a,b) if a > 0 else (-a,-b)
    C = Counter(std(a, b) for a, b in zip(*[iter(AB)] * 2))
    def resolve():
        ans = 1
        cnt = 0
        for (a,b), v in C.items():
            if b > 0:
                if (b,-a) in C:
                    ans *= -1 + pow(2,v,mod) + pow(2,C[(b,-a)], mod) #仲の悪い組み合わせが一緒に入らないように，別々に入れるか入れないかを判定 空集合は共通しているので引く
                    ans %= mod
                else:
                    cnt += v
            elif (-b,a) not in C:
                cnt += v
        ans *= pow(2,cnt,mod)
        ans += C[(0,0)] - 1
        print(ans%mod)
    resolve()

def gSQme():
    def reachable(es, source):
    	ret = {source}
    	Q = [source]
    	while Q:
    		cur = Q.pop()
    		for nxt in es[cur]:
    			if nxt not in ret:
    				Q.append(nxt)
    				ret.add(nxt)
    	return ret

    def BellmanFord(V:int, es:list, source=0):
    	INF = float("inf")
    	D = [INF]*V
    	D[source] = 0
    	for _ in range(V):
    		upd = False
    		for f, t, c in es:
    			tmp = D[f] + c
    			if D[t] > tmp:
    				D[t] = tmp
    				upd = True
    		if not upd:
    			return D[-1]
    	else:
    		return None

    def main():
    	N,M,P,*L=map(int,open(0).read().split())
    	fwd = [[] for _ in range(N)]
    	bwd = [[] for _ in range(N)]
    	tmp = []
    	for a,b,c in zip(*[iter(L)]*3):
    		fwd[a-1].append(b-1)
    		bwd[b-1].append(a-1)
    		tmp+=[(a-1,b-1,P-c)]
    	judge = reachable(fwd,0) & reachable(bwd,N-1)
    	ans = BellmanFord(N,[(a,b,c) for a,b,c in tmp if a in judge and b in judge])
    	if ans==None:
    		print(-1)
    	else:
    		print(max(0,-ans))

    def __starting_point():
    	main()
    __starting_point()

