        def __init__(self, n):
            self.n = n
            self.data = [0]*(n+1)
        def add(self, i, x):
            while i <= self.n:
                self.data[i] += x
                i += i & -i
        def get(self, i):
            return self.sum_range(i, i)
        def sum(self, i):
            ret = 0
            while i:
                ret += self.data[i]
                i &= i-1
