class Solution:
    def countTriplets(self, A: List[int]) -> int:
        counters = [0] * (1 << 16)
        counters[0] = len(A)
        for num in A:
            mask = (~num) & ((1 << 16) - 1)
            sm = mask
            while sm != 0:
                counters[sm] += 1
                sm = (sm - 1) & mask

        return sum(counters[num1 & num2] for num1 in A for num2 in A)

primes = [2, 3, 5, 7]

def is_prime(n):
    if n < 2:
        return False
    m = int(n ** .5) + 1
    for p in primes:
        if p >= m: break
        if not n % p:
            return False
    q, d = primes[-1], 4 if (n + 1) % 6 else 2
    while q < m:
        q, d = q + d, 4 - d
        if is_prime(q):
            primes.append(q)
            if not n % q:
                return False
    return True

