class Solution:
     def reverseVowels(self, s):
         """
         :type s: str
         :rtype: str
         """
         vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
         char_list = list(s)
         first, last = 0, len(char_list) - 1
         while first < last:
             while first < last and char_list[first] not in vowels:
                 first += 1
             while first < last and char_list[last] not in vowels:
                 last -= 1
             if first >= last:
                 break
             char_list[first], char_list[last] = char_list[last], char_list[first]
             first += 1
             last -=1
         return "".join(char_list)

from collections import Counter

def longest_palindrome(s):
    c = Counter(filter(str.isalnum, s.lower()))
    return sum(v//2*2 for v in c.values()) + any(v%2 for v in c.values())

