    class CumTree:

        def __init__(self, a, b):
            self.a = a
            self.b = b
            self.count = 0
            if a == b:
                return
            mid = (a + b) // 2
            self.levo = CumTree(a, mid)
            self.desno = CumTree(mid+1, b)

        def manjsi(self, t):
            if self.a >= t:
                return 0
            if self.b < t:
