            return self.levo.manjsi(t) + self.desno.manjsi(t)

        def vstavi(self, t):
            if self.a <= t <= self.b:
                self.count += 1
                if self.a == self.b:
                    return
                self.levo.vstavi(t)
                self.desno.vstavi(t)

