    def check1(nums, target, K):
        for x in nums:
            if K < 0:
                return False
            if x < target:
                K -= target - x
        return K >= 0
    def check2(nums, target, K):
        for x in nums:
            if K < 0:
                return False
            if x > target:
                K -= x - target
        return K >= 0
    l1, r1 = min(nums), avg + 1
    while l1 + 1 < r1:
        mid = (l1 + r1) >> 1
        if check1(nums, mid, k):
            l1 = mid
        else:
            r1 = mid
    if check2(nums, avg + (0 if total % n == 0 else 1), k):
