    s = [ [0 for i in range(60)] for j in range(60) ]
    inv = [ 1 ]
    f[0][0] = s[0][0] = 1

    def pow(x, exp) :
        res = 1
        for i in range(0, 31) :
            if exp & 1 : res = res * x % mod
            exp >>= 1
            if exp == 0 : break
            x = x * x % mod
        return res

