                nb += 1
            elif ch == 'c':
                nc += 1
            if ch == left:
                sf = False
            else:
                tf = False
            left = ch


        if tf:
            return 1
        if n == 3:
            if (nb + nc * 2) % 3:
                return 7 if sf else 6
            else:
