class Solution:
    def canArrange(self, arr: List[int], k: int) -> bool:
        freq = [0] * k

        for n in arr:
            freq[n%k] += 1

        if freq[0] % 2: return False

        for i in range(1, (k//2)+1):
            if freq[i] != freq[k-i]: return False

        if k%2 == 0:
            if freq[k//2]%2: return False

        return True

class Solution:
     def findMaximumXOR(self, nums):
         """
         :type nums: List[int]
         :rtype: int
         """
         ans = 0
         for bit in range(31, -1, -1) :
             ans = (ans << 1) + 1
             pre = set()
             for n in nums :
                 p = (n >> bit) & ans
                 if p in pre :
                     break
                 pre.add(ans - p)
             else :
                 ans -= 1
         return ans

