digits = lambda x: set(str(x))

def LDTA(n):
    if digits(n) == digits(n*n):
        return None

    seen = []
    x = n

    while len(seen) < 10:
        for d in str(x):
            if d not in seen:
                seen.append(d)
        x *= n

    return int(seen[-1])

class Solution:
    def maxScoreSightseeingPair(self, A: List[int]) -> int:
        curmaxsight = A[0] - 1
        curmaxpair = 0
        for sight in A[1:]:
            if sight + curmaxsight > curmaxpair:
                curmaxpair = sight + curmaxsight
            if sight > curmaxsight:
                curmaxsight = sight
            curmaxsight -= 1
        return curmaxpair

